import{_ as t,o as d,c as e,Q as o}from"./chunks/framework.48927342.js";const f=JSON.parse('{"title":"常用介词与用法","description":"","frontmatter":{},"headers":[],"relativePath":"zh/more/maltese/grammar/08-prepositions.md","filePath":"zh/more/maltese/grammar/08-prepositions.md"}'),a={name:"zh/more/maltese/grammar/08-prepositions.md"},i=o('<h1 id="常用介词与用法" tabindex="-1">常用介词与用法 <a class="header-anchor" href="#常用介词与用法" aria-label="Permalink to &quot;常用介词与用法&quot;">​</a></h1><p>介词常和名词、定冠词连用；一部分会与后面的定冠词缩合。介词也可以带人称后缀，形成“对我/和你/在他那里”等形式。下表大致按日常使用频率排序；具体频率会随语境和搭配变化。</p><h2 id="_1-常用介词表" tabindex="-1">1. 常用介词表 <a class="header-anchor" href="#_1-常用介词表" aria-label="Permalink to &quot;1. 常用介词表&quot;">​</a></h2><p>下表先列日常高频介词，再列常见的方向、时间、例外和固定搭配形式。马耳他语词典还会把少见方言、古语、连词用法及屈折形式归入介词条目；本表以现代标准语中实用的介词和介词短语为主。</p><table><thead><tr><th>Malti</th><th>中文义</th><th>English gloss</th><th>用法/搭配</th></tr></thead><tbody><tr><td>f&#39; / fi</td><td>在……里、在……</td><td>in; at</td><td><code>fil-kamra</code>：在房间里；<code>f&#39;Malta</code>：在马耳他</td></tr><tr><td>b&#39; / bi</td><td>用、以；和</td><td>with; by; using</td><td><code>b&#39;idek</code>：用你的手；<code>bi flus</code>：用钱（<code>bi</code> 常见于辅音连缀前）</td></tr><tr><td>ma&#39;</td><td>和、与</td><td>with</td><td><code>ma&#39; ħabib</code>：和朋友一起</td></tr><tr><td>għal</td><td>为了、给、朝向</td><td>for; to; toward</td><td><code>għalik</code>：给你；<code>għal Malta</code>：去/朝马耳他（依上下文）</td></tr><tr><td>minn</td><td>从、来自；比较时的“比”</td><td>from; than</td><td><code>minn Malta</code>：来自马耳他</td></tr><tr><td>ta&#39;</td><td>……的；属于</td><td>of; belonging to</td><td><code>bieb ta&#39; dar</code>：房子的门</td></tr><tr><td>fuq</td><td>在……上；关于</td><td>on; about</td><td><code>fuq il-mejda</code>：在桌子上</td></tr><tr><td>lil</td><td>给、向（人）</td><td>to; for (a person)</td><td><code>lil ommi</code>：给/向我母亲</td></tr><tr><td>għand</td><td>在某人处；有</td><td>at; with; have</td><td><code>għandi ktieb</code>：我有一本书；<code>għand it-tabib</code>：在医生那里</td></tr><tr><td>wara</td><td>在……后面；之后</td><td>behind; after</td><td><code>wara l-ikla</code>：饭后</td></tr><tr><td>sa</td><td>到、直到；远至</td><td>until; as far as</td><td><code>sa għada</code>：直到明天</td></tr><tr><td>lejn</td><td>朝向、往</td><td>toward</td><td><code>lejn il-port</code>：朝港口</td></tr><tr><td>taħt</td><td>在……下面</td><td>under</td><td><code>taħt is-siġġu</code>：在椅子下面</td></tr><tr><td>bejn</td><td>在……之间</td><td>between</td><td><code>bejn iż-żewġt idjar</code>：在两所房子之间</td></tr><tr><td>qabel</td><td>在……之前</td><td>before</td><td><code>qabel ix-xogħol</code>：上班前</td></tr><tr><td>ħdejn</td><td>在……旁边</td><td>beside; next to</td><td><code>ħdejn l-iskola</code>：在学校旁边</td></tr><tr><td>quddiem</td><td>在……前面</td><td>in front of</td><td><code>quddiem id-dar</code>：在房子前面</td></tr><tr><td>madwar</td><td>围绕、在……周围；大约</td><td>around; about</td><td><code>madwar il-mejda</code>：围着桌子</td></tr><tr><td>dwar</td><td>关于</td><td>about; concerning</td><td><code>ktieb dwar Malta</code>：一本关于马耳他的书</td></tr><tr><td>minħabba</td><td>因为、由于</td><td>because of</td><td><code>minħabba x-xita</code>：因为下雨</td></tr><tr><td>bħal</td><td>像、如同</td><td>like; as</td><td><code>bħal dan</code>：像这个</td></tr><tr><td>ġewwa</td><td>在……里面；进入</td><td>inside; into</td><td><code>ġewwa d-dar</code>：在屋里</td></tr><tr><td>barra</td><td>在……外面；到外面</td><td>outside; out of</td><td><code>barra mid-dar</code>：在房子外面</td></tr><tr><td>mingħajr</td><td>没有、不带</td><td>without</td><td><code>mingħajr zokkor</code>：不加糖</td></tr><tr><td>kontra</td><td>反对；靠着</td><td>against</td><td><code>kontra l-ħajt</code>：靠着墙</td></tr><tr><td>skont</td><td>根据、按照</td><td>according to</td><td><code>skont ir-regoli</code>：按照规则</td></tr><tr><td>tul</td><td>沿着；在……期间</td><td>along; throughout</td><td><code>tul it-triq</code>：沿着道路</td></tr></tbody></table><h3 id="其他常见介词与固定搭配" tabindex="-1">其他常见介词与固定搭配 <a class="header-anchor" href="#其他常见介词与固定搭配" aria-label="Permalink to &quot;其他常见介词与固定搭配&quot;">​</a></h3><table><thead><tr><th>Malti</th><th>中文义</th><th>English gloss</th><th>用法/搭配</th></tr></thead><tbody><tr><td>bla</td><td>不加、没有（后接无冠词名词）</td><td>without</td><td><code>bla ħalib</code>：不加牛奶；否定介词搭配多用 <code>mingħajr</code></td></tr><tr><td>bħala</td><td>作为；例如</td><td>as; in the capacity of</td><td><code>bħala għalliem</code>：作为一名教师</td></tr><tr><td>biswit</td><td>对面；与 <code>ta&#39;</code> 连用表示“在……对面”</td><td>opposite; opposite to</td><td><code>biswit l-iskola</code>：在学校对面</td></tr><tr><td>faċċata ta&#39;</td><td>在……正对面</td><td>facing; opposite</td><td><code>faċċata tal-iskola</code>：在学校正对面</td></tr><tr><td>flok</td><td>代替；而不是</td><td>instead of</td><td><code>flok kafè</code>：代替咖啡</td></tr><tr><td>fost</td><td>在……之中</td><td>among</td><td><code>fost il-ħbieb</code>：在朋友之中</td></tr><tr><td>ġo</td><td>在……里面（<code>ġewwa</code> 的缩合形式）</td><td>inside; into</td><td><code>ġo borża</code>：在袋子里</td></tr><tr><td>għajr</td><td>除……以外；除了</td><td>except; other than</td><td><code>kulħadd għajr Ana</code>：除了 Ana 以外的所有人</td></tr><tr><td>ħlief</td><td>除……以外；但是</td><td>except; but</td><td><code>xejn ħlief ktieb</code>：除了书什么也没有</td></tr><tr><td>maġenb</td><td>在……旁边</td><td>next to; beside</td><td><code>maġenb id-dar</code>：在房子旁边</td></tr><tr><td>matul</td><td>在……期间；沿着；贯穿一段时间</td><td>during; throughout; along</td><td><code>matul il-festa</code>：节庆期间（通常指覆盖较长时段）</td></tr><tr><td>minflok</td><td>代替；而不是</td><td>instead of</td><td><code>minflok il-karozza</code>：代替汽车</td></tr><tr><td>minkejja</td><td>尽管</td><td>despite; in spite of</td><td><code>minkejja x-xita</code>：尽管下雨</td></tr><tr><td>qalb</td><td>在……中央/之中</td><td>amid; in the middle of</td><td><code>qalb il-belt</code>：在城市中心</td></tr><tr><td>qrib</td><td>靠近</td><td>near</td><td><code>qrib l-iskola</code>：靠近学校</td></tr><tr><td>sakemm</td><td>直到</td><td>until</td><td><code>sakemm tasal</code>：直到你到达</td></tr><tr><td>waqt</td><td>在……时候；在……期间</td><td>at the time of; during</td><td><code>waqt il-laqgħa</code>：会议期间（强调时间重合）</td></tr></tbody></table><h2 id="_2-定冠词组合与缩合" tabindex="-1">2. 定冠词组合与缩合 <a class="header-anchor" href="#_2-定冠词组合与缩合" aria-label="Permalink to &quot;2. 定冠词组合与缩合&quot;">​</a></h2><p>马耳他语定冠词的基本形式是 <code>il-</code>，在元音或某些辅音前会写作 <code>l-</code>、<code>is-</code>、<code>id-</code>、<code>it-</code> 等。下表每格展示介词和该类冠词的组合模板；带连字符表示缩合，留空格表示不缩合。实际使用时，把表格末尾的连字符接上名词词干，例如 <code>fil-kamra</code>、<code>fuq is-suq</code>。<code>bla</code> 通常直接接无冠词名词，<code>sakemm</code> 通常引导从句，因此不机械地接这五种定冠词形式。</p><table><thead><tr><th>介词/短语</th><th>中文</th><th>English</th><th>+ il-</th><th>+ l-</th><th>+ is-</th><th>+ id-</th><th>+ it-</th></tr></thead><tbody><tr><td>f&#39; / fi</td><td>在……里；在……</td><td>in; at</td><td><code>fil-</code></td><td><code>fl-</code></td><td><code>fis-</code></td><td><code>fid-</code></td><td><code>fit-</code></td></tr><tr><td>b&#39; / bi</td><td>用、以；和</td><td>with; by</td><td><code>bil-</code></td><td><code>bl-</code></td><td><code>bis-</code></td><td><code>bid-</code></td><td><code>bit-</code></td></tr><tr><td>ma&#39;</td><td>和、与</td><td>with</td><td><code>mal-</code></td><td><code>mal-</code></td><td><code>mas-</code></td><td><code>mad-</code></td><td><code>mat-</code></td></tr><tr><td>għal</td><td>为了；给；朝向</td><td>for; to; toward</td><td><code>għall-</code></td><td><code>għall-</code></td><td><code>għas-</code></td><td><code>għad-</code></td><td><code>għat-</code></td></tr><tr><td>minn</td><td>从；来自；比</td><td>from; than</td><td><code>mill-</code></td><td><code>mill-</code></td><td><code>mis-</code></td><td><code>mid-</code></td><td><code>mit-</code></td></tr><tr><td>ta&#39;</td><td>……的；属于</td><td>of; belonging to</td><td><code>tal-</code></td><td><code>tal-</code></td><td><code>tas-</code></td><td><code>tad-</code></td><td><code>tat-</code></td></tr><tr><td>fuq</td><td>在……上；关于</td><td>on; about</td><td><code>fuq il-</code></td><td><code>fuq l-</code></td><td><code>fuq is-</code></td><td><code>fuq id-</code></td><td><code>fuq it-</code></td></tr><tr><td>lil</td><td>给、向（人）</td><td>to; for (a person)</td><td><code>lill-</code></td><td><code>lill-</code></td><td><code>lis-</code></td><td><code>lid-</code></td><td><code>lit-</code></td></tr><tr><td>għand</td><td>在某人处；有</td><td>at; with; have</td><td><code>għand il-</code></td><td><code>għand l-</code></td><td><code>għand is-</code></td><td><code>għand id-</code></td><td><code>għand it-</code></td></tr><tr><td>wara</td><td>在……后面；之后</td><td>behind; after</td><td><code>wara l-</code></td><td><code>wara l-</code></td><td><code>wara s-</code></td><td><code>wara d-</code></td><td><code>wara t-</code></td></tr><tr><td>sa</td><td>到；直到</td><td>until; as far as</td><td><code>sal-</code></td><td><code>sal-</code></td><td><code>sas-</code></td><td><code>sad-</code></td><td><code>sat-</code></td></tr><tr><td>lejn</td><td>朝向、往</td><td>toward</td><td><code>lejn il-</code></td><td><code>lejn l-</code></td><td><code>lejn is-</code></td><td><code>lejn id-</code></td><td><code>lejn it-</code></td></tr><tr><td>taħt</td><td>在……下面</td><td>under</td><td><code>taħt il-</code></td><td><code>taħt l-</code></td><td><code>taħt is-</code></td><td><code>taħt id-</code></td><td><code>taħt it-</code></td></tr><tr><td>bejn</td><td>在……之间</td><td>between</td><td><code>bejn il-</code></td><td><code>bejn l-</code></td><td><code>bejn is-</code></td><td><code>bejn id-</code></td><td><code>bejn it-</code></td></tr><tr><td>qabel</td><td>在……之前</td><td>before</td><td><code>qabel il-</code></td><td><code>qabel l-</code></td><td><code>qabel is-</code></td><td><code>qabel id-</code></td><td><code>qabel it-</code></td></tr><tr><td>ħdejn</td><td>在……旁边</td><td>beside; next to</td><td><code>ħdejn il-</code></td><td><code>ħdejn l-</code></td><td><code>ħdejn is-</code></td><td><code>ħdejn id-</code></td><td><code>ħdejn it-</code></td></tr><tr><td>quddiem</td><td>在……前面</td><td>in front of</td><td><code>quddiem il-</code></td><td><code>quddiem l-</code></td><td><code>quddiem is-</code></td><td><code>quddiem id-</code></td><td><code>quddiem it-</code></td></tr><tr><td>madwar</td><td>围绕；大约</td><td>around; about</td><td><code>madwar il-</code></td><td><code>madwar l-</code></td><td><code>madwar is-</code></td><td><code>madwar id-</code></td><td><code>madwar it-</code></td></tr><tr><td>dwar</td><td>关于</td><td>about; concerning</td><td><code>dwar il-</code></td><td><code>dwar l-</code></td><td><code>dwar is-</code></td><td><code>dwar id-</code></td><td><code>dwar it-</code></td></tr><tr><td>minħabba</td><td>因为、由于</td><td>because of</td><td><code>minħabba l-</code></td><td><code>minħabba l-</code></td><td><code>minħabba s-</code></td><td><code>minħabba d-</code></td><td><code>minħabba t-</code></td></tr><tr><td>bħal</td><td>像、如同</td><td>like; as</td><td><code>bħall-</code></td><td><code>bħall-</code></td><td><code>bħas-</code></td><td><code>bħad-</code></td><td><code>bħat-</code></td></tr><tr><td>ġewwa</td><td>在……里面；进入</td><td>inside; into</td><td><code>ġewwa l-</code></td><td><code>ġewwa l-</code></td><td><code>ġewwa s-</code></td><td><code>ġewwa d-</code></td><td><code>ġewwa t-</code></td></tr><tr><td>barra</td><td>在……外面</td><td>outside; out of</td><td><code>barra mill-</code></td><td><code>barra mill-</code></td><td><code>barra mis-</code></td><td><code>barra mid-</code></td><td><code>barra mit-</code></td></tr><tr><td>mingħajr</td><td>没有、不带</td><td>without</td><td><code>mingħajr il-</code></td><td><code>mingħajr l-</code></td><td><code>mingħajr is-</code></td><td><code>mingħajr id-</code></td><td><code>mingħajr it-</code></td></tr><tr><td>kontra</td><td>反对；靠着</td><td>against</td><td><code>kontra l-</code></td><td><code>kontra l-</code></td><td><code>kontra s-</code></td><td><code>kontra d-</code></td><td><code>kontra t-</code></td></tr><tr><td>skont</td><td>根据、按照</td><td>according to</td><td><code>skont il-</code></td><td><code>skont l-</code></td><td><code>skont is-</code></td><td><code>skont id-</code></td><td><code>skont it-</code></td></tr><tr><td>tul</td><td>沿着；在……期间</td><td>along; throughout</td><td><code>tul il-</code></td><td><code>tul l-</code></td><td><code>tul is-</code></td><td><code>tul id-</code></td><td><code>tul it-</code></td></tr><tr><td>bla</td><td>不加、没有</td><td>without</td><td>通常不接定冠词</td><td>通常不接定冠词</td><td>通常不接定冠词</td><td>通常不接定冠词</td><td>通常不接定冠词</td></tr><tr><td>bħala</td><td>作为</td><td>as; in the capacity of</td><td><code>bħala l-</code></td><td><code>bħala l-</code></td><td><code>bħala s-</code></td><td><code>bħala d-</code></td><td><code>bħala t-</code></td></tr><tr><td>biswit</td><td>在……对面</td><td>opposite; opposite to</td><td><code>biswit il-</code></td><td><code>biswit l-</code></td><td><code>biswit is-</code></td><td><code>biswit id-</code></td><td><code>biswit it-</code></td></tr><tr><td>faċċata ta&#39;</td><td>在……正对面</td><td>facing; opposite</td><td><code>faċċata tal-</code></td><td><code>faċċata tal-</code></td><td><code>faċċata tas-</code></td><td><code>faċċata tad-</code></td><td><code>faċċata tat-</code></td></tr><tr><td>flok</td><td>代替；而不是</td><td>instead of</td><td><code>flok il-</code></td><td><code>flok l-</code></td><td><code>flok is-</code></td><td><code>flok id-</code></td><td><code>flok it-</code></td></tr><tr><td>fost</td><td>在……之中</td><td>among</td><td><code>fost il-</code></td><td><code>fost l-</code></td><td><code>fost is-</code></td><td><code>fost id-</code></td><td><code>fost it-</code></td></tr><tr><td>ġo</td><td>在……里面</td><td>inside; into</td><td><code>ġol-</code></td><td><code>ġol-</code></td><td><code>ġos-</code></td><td><code>ġod-</code></td><td><code>ġot-</code></td></tr><tr><td>għajr</td><td>除……以外</td><td>except; other than</td><td><code>għajr il-</code></td><td><code>għajr l-</code></td><td><code>għajr is-</code></td><td><code>għajr id-</code></td><td><code>għajr it-</code></td></tr><tr><td>ħlief</td><td>除……以外</td><td>except; but</td><td><code>ħlief il-</code></td><td><code>ħlief l-</code></td><td><code>ħlief is-</code></td><td><code>ħlief id-</code></td><td><code>ħlief it-</code></td></tr><tr><td>maġenb</td><td>在……旁边</td><td>next to; beside</td><td><code>maġenb il-</code></td><td><code>maġenb l-</code></td><td><code>maġenb is-</code></td><td><code>maġenb id-</code></td><td><code>maġenb it-</code></td></tr><tr><td>matul</td><td>在……期间；沿着</td><td>during; throughout; along</td><td><code>matul il-</code></td><td><code>matul l-</code></td><td><code>matul is-</code></td><td><code>matul id-</code></td><td><code>matul it-</code></td></tr><tr><td>minflok</td><td>代替；而不是</td><td>instead of</td><td><code>minflok il-</code></td><td><code>minflok l-</code></td><td><code>minflok is-</code></td><td><code>minflok id-</code></td><td><code>minflok it-</code></td></tr><tr><td>minkejja</td><td>尽管</td><td>despite; in spite of</td><td><code>minkejja l-</code></td><td><code>minkejja l-</code></td><td><code>minkejja s-</code></td><td><code>minkejja d-</code></td><td><code>minkejja t-</code></td></tr><tr><td>qalb</td><td>在……中央/之中</td><td>amid; in the middle of</td><td><code>qalb il-</code></td><td><code>qalb l-</code></td><td><code>qalb is-</code></td><td><code>qalb id-</code></td><td><code>qalb it-</code></td></tr><tr><td>qrib</td><td>靠近</td><td>near</td><td><code>qrib il-</code></td><td><code>qrib l-</code></td><td><code>qrib is-</code></td><td><code>qrib id-</code></td><td><code>qrib it-</code></td></tr><tr><td>sakemm</td><td>直到（引导从句）</td><td>until (a clause)</td><td>不直接接定冠词名词</td><td>不直接接定冠词名词</td><td>不直接接定冠词名词</td><td>不直接接定冠词名词</td><td>不直接接定冠词名词</td></tr><tr><td>waqt</td><td>在……时候；期间</td><td>at the time of; during</td><td><code>waqt il-</code></td><td><code>waqt l-</code></td><td><code>waqt is-</code></td><td><code>waqt id-</code></td><td><code>waqt it-</code></td></tr></tbody></table><p>真正缩合的常见组包括 <code>f&#39; / fi</code>、<code>b&#39; / bi</code>、<code>ma&#39;</code>、<code>għal</code>、<code>minn</code>、<code>ta&#39;</code>、<code>sa</code>、<code>lil</code>、<code>bħal</code> 和 <code>ġo</code>；<code>faċċata ta&#39;</code>、<code>barra minn</code> 这类短语缩合的是其中的 <code>ta&#39;</code> 或 <code>minn</code>。其他介词通常与定冠词分写。<code>il-</code>/<code>l-</code> 两列在一些缩合形式中结果相同；表格重复列出，是为了对照名词冠词的拼写变化，而不是表示两套不同规则。</p><h2 id="_3-方向、来源与位置" tabindex="-1">3. 方向、来源与位置 <a class="header-anchor" href="#_3-方向、来源与位置" aria-label="Permalink to &quot;3. 方向、来源与位置&quot;">​</a></h2><ul><li><code>immur Malta</code>：我去马耳他。（地名搭配不一定需要冠词）</li><li><code>niġi minn Malta</code>：我来自马耳他。</li><li><code>Il-ktieb qiegħed fuq il-mejda.</code>：书在桌子上。</li><li><code>Il-qattus qiegħed taħt is-sodda.</code>：猫在床下。</li><li><code>L-iskola tinsab ħdejn id-dar.</code>：学校在房子旁边。</li></ul><h2 id="_4-时间介词" tabindex="-1">4. 时间介词 <a class="header-anchor" href="#_4-时间介词" aria-label="Permalink to &quot;4. 时间介词&quot;">​</a></h2><ul><li><code>filgħodu</code>：早上；<code>wara nofsinhar</code>：下午；<code>filgħaxija</code>：晚上。</li><li><code>f&#39;Ġunju</code>：在六月。</li><li><code>nhar it-Tnejn</code>：星期一这一天。</li><li><code>qabel l-ikel</code>：午餐/吃饭之前；<code>wara l-ikel</code>：吃饭之后。</li></ul><h2 id="_5-għand-表示-有" tabindex="-1">5. <code>għand</code> 表示“有” <a class="header-anchor" href="#_5-għand-表示-有" aria-label="Permalink to &quot;5. `għand` 表示“有”&quot;">​</a></h2><p>马耳他语常用 <code>għand</code> 加人称形式表达“某人有某物”，不是直接用英语式的 have 动词：</p><table><thead><tr><th>中文</th><th>Malti</th></tr></thead><tbody><tr><td>我有</td><td>għandi</td></tr><tr><td>你有</td><td>għandek</td></tr><tr><td>他有</td><td>għandu</td></tr><tr><td>她有</td><td>għandha</td></tr><tr><td>我们有</td><td>għandna</td></tr><tr><td>你们有</td><td>għandkom</td></tr><tr><td>他们/她们有</td><td>għandhom</td></tr></tbody></table><p>例句：<code>Għandi karozza.</code>（我有一辆车。）<code>Għandek kelb?</code>（你有狗吗？）</p><h2 id="_6-学习建议" tabindex="-1">6. 学习建议 <a class="header-anchor" href="#_6-学习建议" aria-label="Permalink to &quot;6. 学习建议&quot;">​</a></h2><p>把介词和名词一起记，不要只背中文单义；<code>f&#39;</code>、<code>għal</code>、<code>minn</code> 等词会根据上下文表达不同关系。也留意冠词和介词的缩合，如 <code>fil-</code>、<code>bil-</code>、<code>mal-</code>、<code>għall-</code>、<code>mill-</code>、<code>tal-</code>。</p><h2 id="_7-按常用程度排列的介词例句" tabindex="-1">7. 按常用程度排列的介词例句 <a class="header-anchor" href="#_7-按常用程度排列的介词例句" aria-label="Permalink to &quot;7. 按常用程度排列的介词例句&quot;">​</a></h2><table><thead><tr><th style="text-align:right;">#</th><th>介词</th><th>中文</th><th>English</th><th>Malti</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td>f&#39; / fi</td><td>我在马耳他。</td><td>I am in Malta.</td><td>Jien qiegħed f&#39;Malta.</td></tr><tr><td style="text-align:right;">2</td><td>b&#39; / bi</td><td>我用钥匙开门。</td><td>I open the door with a key.</td><td>Niftaħ il-bieb b&#39;ċavetta.</td></tr><tr><td style="text-align:right;">3</td><td>ma&#39;</td><td>我和朋友一起工作。</td><td>I work with a friend.</td><td>Naħdem ma&#39; ħabib.</td></tr><tr><td style="text-align:right;">4</td><td>għal</td><td>这份礼物是给你的。</td><td>This gift is for you.</td><td>Dan ir-rigal huwa għalik.</td></tr><tr><td style="text-align:right;">5</td><td>minn</td><td>她来自马耳他。</td><td>She is from Malta.</td><td>Hi minn Malta.</td></tr><tr><td style="text-align:right;">6</td><td>ta&#39;</td><td>这是安娜的书。</td><td>This is Anna&#39;s book.</td><td>Dan hu l-ktieb ta&#39; Anna.</td></tr><tr><td style="text-align:right;">7</td><td>fuq</td><td>杯子在桌子上。</td><td>The cup is on the table.</td><td>It-tazza qiegħda fuq il-mejda.</td></tr><tr><td style="text-align:right;">8</td><td>lil</td><td>我给母亲打电话。</td><td>I call my mother.</td><td>Inċempel lil ommi.</td></tr><tr><td style="text-align:right;">9</td><td>għand</td><td>我有一辆车。</td><td>I have a car.</td><td>Għandi karozza.</td></tr><tr><td style="text-align:right;">10</td><td>wara</td><td>我们饭后去。</td><td>We go after the meal.</td><td>Immorru wara l-ikla.</td></tr><tr><td style="text-align:right;">11</td><td>sa</td><td>我会待到明天。</td><td>I will stay until tomorrow.</td><td>Se nibqa&#39; sa għada.</td></tr><tr><td style="text-align:right;">12</td><td>lejn</td><td>汽车正驶向港口。</td><td>The car is heading toward the port.</td><td>Il-karozza sejra lejn il-port.</td></tr><tr><td style="text-align:right;">13</td><td>taħt</td><td>猫在椅子下面。</td><td>The cat is under the chair.</td><td>Il-qattus qiegħed taħt is-siġġu.</td></tr><tr><td style="text-align:right;">14</td><td>bejn</td><td>房子在学校和商店之间。</td><td>The house is between the school and the shop.</td><td>Id-dar tinsab bejn l-iskola u l-ħanut.</td></tr><tr><td style="text-align:right;">15</td><td>qabel</td><td>我上班前喝咖啡。</td><td>I drink coffee before work.</td><td>Nixrob kafè qabel ix-xogħol.</td></tr><tr><td style="text-align:right;">16</td><td>ħdejn</td><td>学校在房子旁边。</td><td>The school is next to the house.</td><td>L-iskola tinsab ħdejn id-dar.</td></tr><tr><td style="text-align:right;">17</td><td>quddiem</td><td>汽车停在房子前面。</td><td>The car is parked in front of the house.</td><td>Il-karozza qiegħda quddiem id-dar.</td></tr><tr><td style="text-align:right;">18</td><td>madwar</td><td>人们围着桌子坐着。</td><td>People are sitting around the table.</td><td>In-nies qegħdin bilqiegħda madwar il-mejda.</td></tr><tr><td style="text-align:right;">19</td><td>dwar</td><td>这本书是关于马耳他的。</td><td>This book is about Malta.</td><td>Dan il-ktieb huwa dwar Malta.</td></tr><tr><td style="text-align:right;">20</td><td>minħabba</td><td>因为下雨，我们待在家里。</td><td>Because of the rain, we are staying at home.</td><td>Minħabba x-xita, nibqgħu d-dar.</td></tr><tr><td style="text-align:right;">21</td><td>bħal</td><td>她像母亲。</td><td>She is like her mother.</td><td>Hi bħal ommha.</td></tr><tr><td style="text-align:right;">22</td><td>ġewwa</td><td>孩子们在屋里。</td><td>The children are inside the house.</td><td>It-tfal qegħdin ġewwa d-dar.</td></tr><tr><td style="text-align:right;">23</td><td>barra</td><td>我们在房子外面。</td><td>We are outside the house.</td><td>Qegħdin barra mid-dar.</td></tr><tr><td style="text-align:right;">24</td><td>mingħajr</td><td>请给我不加糖的咖啡。</td><td>Coffee without sugar, please.</td><td>Kafè mingħajr zokkor, jekk jogħġbok.</td></tr><tr><td style="text-align:right;">25</td><td>kontra</td><td>椅子靠着墙。</td><td>The chair is against the wall.</td><td>Is-siġġu qiegħed kontra l-ħajt.</td></tr><tr><td style="text-align:right;">26</td><td>skont</td><td>根据时间表，公交车准时出发。</td><td>According to the timetable, the bus leaves on time.</td><td>Skont l-iskeda, ix-xarabank jitlaq fil-ħin.</td></tr><tr><td style="text-align:right;">27</td><td>tul</td><td>路边有很多树。</td><td>There are many trees along the road.</td><td>Tul it-triq hemm ħafna siġar.</td></tr><tr><td style="text-align:right;">28</td><td>bla</td><td>不加牛奶的咖啡。</td><td>Coffee without milk.</td><td>Kafè bla ħalib.</td></tr><tr><td style="text-align:right;">29</td><td>bħala</td><td>她是一名教师。</td><td>She works as a teacher.</td><td>Hi taħdem bħala għalliema.</td></tr><tr><td style="text-align:right;">30</td><td>biswit</td><td>酒店在海边对面。</td><td>The hotel is opposite the sea.</td><td>Il-lukanda tinsab biswit il-baħar.</td></tr><tr><td style="text-align:right;">31</td><td>faċċata ta&#39;</td><td>银行在学校正对面。</td><td>The bank is facing the school.</td><td>Il-bank jinsab faċċata tal-iskola.</td></tr><tr><td style="text-align:right;">32</td><td>flok</td><td>我喝茶代替咖啡。</td><td>I drink tea instead of coffee.</td><td>Nixrob tè flok kafè.</td></tr><tr><td style="text-align:right;">33</td><td>fost</td><td>孩子在朋友们中间。</td><td>The child is among his friends.</td><td>It-tifel qiegħed fost sħabu.</td></tr><tr><td style="text-align:right;">34</td><td>ġo</td><td>把书放进袋子里。</td><td>Put the book in a bag.</td><td>Poġġi l-ktieb ġo borża.</td></tr><tr><td style="text-align:right;">35</td><td>għajr</td><td>除了 Ana，所有人都来了。</td><td>Everyone came except Ana.</td><td>Kulħadd ġie għajr Ana.</td></tr><tr><td style="text-align:right;">36</td><td>ħlief</td><td>除了这本书以外的一切。</td><td>Everything except this book.</td><td>Kollox ħlief dan il-ktieb.</td></tr><tr><td style="text-align:right;">37</td><td>maġenb</td><td>商店在房子旁边。</td><td>The shop is next to the house.</td><td>Il-ħanut qiegħed maġenb id-dar.</td></tr><tr><td style="text-align:right;">38</td><td>matul</td><td>雨在夜间停了。</td><td>The rain stopped during the night.</td><td>Ix-xita waqfet matul il-lejl.</td></tr><tr><td style="text-align:right;">39</td><td>minflok</td><td>我坐汽车而不坐公交车。</td><td>I take the car instead of the bus.</td><td>Nieħu l-karozza minflok ix-xarabank.</td></tr><tr><td style="text-align:right;">40</td><td>minkejja</td><td>尽管下雨，我们还是出门。</td><td>Despite the rain, we go out.</td><td>Minkejja x-xita, noħorġu.</td></tr><tr><td style="text-align:right;">41</td><td>qalb</td><td>房子在森林中央。</td><td>The house is in the middle of the forest.</td><td>Id-dar tinsab qalb il-bosk.</td></tr><tr><td style="text-align:right;">42</td><td>qrib</td><td>我住在学校附近。</td><td>I live near the school.</td><td>Ngħix qrib l-iskola.</td></tr><tr><td style="text-align:right;">43</td><td>sakemm</td><td>等到我到达。</td><td>Wait until I arrive.</td><td>Stenna sakemm nasal.</td></tr><tr><td style="text-align:right;">44</td><td>waqt</td><td>手机在会议期间响了。</td><td>The phone rang during the meeting.</td><td>Il-mowbajl daqq waqt il-laqgħa.</td></tr></tbody></table>',23),c=[i];function r(l,n,s,h,b,g){return d(),e("div",null,c)}const u=t(a,[["render",r]]);export{f as __pageData,u as default};
